$(document).ready(function () {
  if (typeof (Page_Validators) === "undefined") return;

  var v = document.createElement("span");
  v.style.display = "none";
  v.id = "endAfterStartValidator";
  v.controltovalidate = "cr1a2_enddate";
  v.errormessage = "<a href='#cr1a2_enddate_label' referencecontrolid='cr1a2_enddate' onclick='javascript:scrollToAndFocus(\"cr1a2_enddate_label\",\"cr1a2_enddate\");return false;'>End date must be after the start date.</a>";
  v.validationGroup = "";
  v.initialvalue = "";
  v.evaluationfunction = function () {
    var start = $("#cr1a2_startdate").val();      // ISO value held in the hidden input
    var end = $("#cr1a2_enddate").val();
    if (!start || !end) return true;              // let the required validators handle blanks
    return new Date(end) > new Date(start);
  };
  Page_Validators.push(v);
});

