3. Conditionally required field (reason required when status is Other)
function setRequired(fieldId, required, message) {
  var label = $("#" + fieldId + "_label");
  var id = fieldId + "_customRequired";
  if (required) {
    label.parent().addClass("required");                       // shows the asterisk
    if ($.grep(Page_Validators, function (x) { return x.id === id; }).length === 0) {
      var r = document.createElement("span");
      r.style.display = "none"; r.id = id; r.controltovalidate = fieldId;
      r.errormessage = "<a href='#" + fieldId + "_label'>" + message + "</a>";
      r.evaluationfunction = function () { return $.trim($("#" + fieldId).val()) !== ""; };
      Page_Validators.push(r);
    }
  } else {
    label.parent().removeClass("required");
    Page_Validators = $.grep(Page_Validators, function (x) { return x.id !== id; });
  }
}
