// lblCostCentreError.Visible
!IsBlank(txtCostCentre.Text) &&
!IsMatch(Trim(txtCostCentre.Text), "CC-[0-9]{4}", MatchOptions.Complete & MatchOptions.IgnoreCase)

// lblQuantityError.Text:    "Enter a whole number from 1 to 999."
// lblQuantityError.Visible
!IsBlank(txtQuantity.Text) && !IsMatch(Trim(txtQuantity.Text), "[1-9][0-9]{0,2}")

// lblPhoneError.Text:    "Use digits, spaces or hyphens, with an optional + at the start."
// lblPhoneError.Visible  (phone is optional)
!IsBlank(txtPhone.Text) && !IsMatch(Trim(txtPhone.Text), "\+?[0-9][0-9 \-]{5,18}[0-9]")

// btnSubmit.DisplayMode: required fields filled in and no error showing.
// Reading the labels keeps each pattern in one place.
If(
    IsBlank(txtEmail.Text) || IsBlank(txtCostCentre.Text) || IsBlank(txtQuantity.Text) ||
    lblEmailError.Visible || lblCostCentreError.Visible ||
    lblQuantityError.Visible || lblPhoneError.Visible,
    DisplayMode.Disabled,
    DisplayMode.Edit
)

// btnSubmit.OnSelect: write the cleaned-up values, not the raw text
IfError(
    Patch(
        'Equipment Requests',
        Defaults('Equipment Requests'),
        {
            Title: Trim(txtTitle.Text),
            'Requester Email': Lower(Trim(txtEmail.Text)),
            'Cost Centre': Upper(Trim(txtCostCentre.Text)),
            Quantity: Value(Trim(txtQuantity.Text)),
            Phone: Trim(txtPhone.Text)
        }
    );
    Notify("Request sent.", NotificationType.Success);
    Reset(txtTitle); Reset(txtEmail); Reset(txtCostCentre); Reset(txtQuantity); Reset(txtPhone),
    Notify("The request couldn't be sent: " & FirstError.Message, NotificationType.Error)
)

// 1. One value: the request number in a subject such as "RE: [REQ-00042] New laptop".
//    Match returns blank when there is no match, so check before reading .id.
With(
    { m: Match(txtSubject.Text, "\[(?<id>REQ-[0-9]{5})\]") },
    If(IsBlank(m), "", m.id)
)

// 2. Several parts at once: "Sam Lee <sam.lee@contoso.com>"
With(
    { m: Match(txtFrom.Text, "(?<name>[^<]+?)\s*<(?<email>[^>]+)>") },
    If(
        IsBlank(m),
        Notify("Use the form Name <email>.", NotificationType.Warning),
        Set(varContact, { Name: m.name, Email: Lower(m.email) })
    )
)

// 3. Every value: all request numbers mentioned in a notes field.
//    MatchAll returns a table, empty when nothing matches.
galLinkedRequests.Items:
    MatchAll(txtNotes.Text, "REQ-[0-9]{5}")

// Show FullMatch in the gallery, or join them into one line
Concat(MatchAll(txtNotes.Text, "REQ-[0-9]{5}"), FullMatch, ", ")

// How many?
CountRows(MatchAll(txtNotes.Text, "REQ-[0-9]{5}"))

// 4. Turn the matches into IDs you can look up (small tables only)
ForAll(
    MatchAll(txtNotes.Text, "REQ-(?<num>[0-9]{5})"),
    { RequestNumber: Value(num) }
)

// 5. A number out of free text: "Total due: 1250.50 GBP"
Value(Match(txtInvoiceLine.Text, "(?<amount>[0-9]+(?:\.[0-9]{2})?)").amount)
